    /// <summary>
    /// Replaces btnRedirect_Click.
    /// - RedirectResult replaces Response.Redirect(url, true).
    /// - No ThreadAbortException exists in .NET 8; no catch block needed.
    /// - Use HttpContext.RequestAborted for long-running work cancellation.
    /// </summary>
    [HttpPost("process")]
    public IActionResult Process()
    {
        if (!User.Identity?.IsAuthenticated ?? true)
        {
            return Redirect("/login");
        }

        try
        {
            ProcessRequest(HttpContext.RequestAborted);
            return Redirect("/success");
        }
        catch (OperationCanceledException)
        {
            // Client disconnected — let the framework handle it
            throw;
        }
        catch (Exception ex)
        {
            LogError(ex);
            return Redirect("/error");
        }
    }

    private string GenerateReport() => "col1,col2\nval1,val2";
    private void ProcessRequest(CancellationToken ct = default) { /* work */ }
    private void LogError(Exception ex) { /* logging */ }
}
